import java.util.*;

class Solution {
    public List<List<Integer>> copyRandomList(int[] vals, int[] next, int[] shortcut, int head) {
        int n = vals.length;
        int[] pos = new int[n];                  // slot -> position in list order
        List<Integer> order = new ArrayList<>();
        for (int s = head; s != -1; s = next[s]) {
            pos[s] = order.size();               // pass 1: number the nodes
            order.add(s);
        }
        List<List<Integer>> res = new ArrayList<>();
        for (int s : order) {                    // pass 2: translate shortcuts
            int sc = shortcut[s] == -1 ? -1 : pos[shortcut[s]];
            res.add(Arrays.asList(vals[s], sc));
        }
        return res;
    }
}

