class Solution:
    def copyRandomList(self, vals: List[int], next: List[int], shortcut: List[int], head: int) -> List[List[int]]:
        pos = {}; order = []; c = head
        while c != -1: pos[c] = len(order); order.append(c); c = next[c]
        return [[vals[s], pos[shortcut[s]] if shortcut[s] != -1 else -1] for s in order]

