function copyRandomList(vals, next, shortcut, head) {
  const nodes = new Map(); for (let c = head; c !== -1; c = next[c]) nodes.set(c, { val: vals[c], next: null, sc: null });
  let first = null, prev = null;
  for (let c = head; c !== -1; c = next[c]) { const n = nodes.get(c); if (prev) prev.next = n; else first = n; prev = n; n.sc = shortcut[c] === -1 ? null : nodes.get(shortcut[c]); }
  const idx = new Map(); let i = 0; for (let n = first; n; n = n.next) idx.set(n, i++);
  const out = []; for (let n = first; n; n = n.next) out.push([n.val, n.sc ? idx.get(n.sc) : -1]); return out;
}
